def hamming_distance(p, q):
    """
    Compute the Hamming distance between strings p and q.
    It is the number of positions where the characters differ.
    """
    return sum(1 for a, b in zip(p, q) if a != b)

def approximate_pattern_matching(Pattern, Text, d):
    """
    Find all starting positions where Pattern appears in Text with at most d mismatches.
    
    Parameters:
        Pattern (str): The pattern to search for.
        Text (str): The text (genome) to search within.
        d (int): The maximum number of allowed mismatches.
    
    Returns:
        list: A list of starting positions (0-based) where Pattern appears with ≤ d mismatches.
    """
    positions = []
    k = len(Pattern)
    for i in range(len(Text) - k + 1):
        substring = Text[i:i+k]
        if hamming_distance(Pattern, substring) <= d:
            positions.append(i)
    return positions

if __name__ == "__main__":
    # Sample input
    Pattern = "CAAGGCTGCC"
    Text = ""
    d = 6
    
    # Find approximate occurrences
    result_positions = approximate_pattern_matching(Pattern, Text, d)
    
    # Print results as space-separated integers
    print(" ".join(map(str, result_positions)))